// === sf-pg-writer v10.1: 事件驱动队列 + 自适应批量 ===
var pg = global.get('pg');
var DEBUG = global.get('edge_debug') || false;
var MAX_QUEUE = 10000;  // Max queue size before dropping
// 🔧 P1#2: BATCH_SIZE 持久化，避免每次入队重置为200
var BATCH_SIZE = global.get('edge_pg_batch_size') || 200;

var records = (msg.payload && msg.payload.pgRecords) ? msg.payload.pgRecords : [];
if (records.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: 'no records' });
    return null;
}

// === Enqueue ===
var queue = global.get('edge_pg_queue') || [];
var totalLen = queue.length + records.length;

if (totalLen > MAX_QUEUE) {
    var dropCount = totalLen - MAX_QUEUE;
    // 🔧 P0#1: 如果 drop 超过队列现有长度，同步裁剪 records
    if (dropCount >= queue.length) {
        records = records.slice(dropCount - queue.length);
        queue = [];
    } else {
        queue = queue.slice(dropCount);
    }
    node.warn('[PG-Writer] Queue overflow! Dropped ' + dropCount + ' oldest records. Current: ' + (queue.length + records.length));
    // Alert via global for sf-monitor to pick up
    var alerts = global.get('edge_recentAlerts') || [];
    alerts.push({
        alertType: 'PG_QUEUE_OVERFLOW',
        deviceId: 0,
        deviceName: 'PG-Writer',
        msg: 'Queue overflow, dropped ' + dropCount + ' records',
        ts: new Date().toISOString()
    });
    if (alerts.length > 20) alerts = alerts.slice(-20);
    global.set('edge_recentAlerts', alerts);
    // 🔍 输出溢出告警
    node.send({ payload: { event: 'overflow', dropped: dropCount, queueSize: queue.length } });
}

queue = queue.concat(records);
global.set('edge_pg_queue', queue);

// 🔍 输出入队确认（DEBUG模式）
if (DEBUG) {
    node.send({ payload: { event: 'enqueued', count: records.length, queueSize: queue.length } });
}

if (DEBUG) node.status({ fill: 'yellow', shape: 'dot', text: 'Q:' + queue.length });

// === Event-driven write: trigger only if not already writing ===
if (global.get('edge_pg_writing')) {
    // Write in progress, data will be picked up after current batch completes
    return null;
}

// Start writing
startWrite();
return null;

// ===== Internal write function =====
function startWrite() {
    global.set('edge_pg_writing', true);
    doWrite();
}

function doWrite() {
    var q = global.get('edge_pg_queue') || [];
    if (q.length === 0) {
        global.set('edge_pg_writing', false);
        node.status({ fill: 'green', shape: 'dot', text: 'idle' });
        // 🔍 输出空闲状态
        node.send({ payload: { event: 'idle' } });
        return;
    }

    // Adaptive batch size: bigger queue → bigger batch
    var batchSize = BATCH_SIZE;
    if (q.length > 5000) batchSize = 500;
    else if (q.length > 2000) batchSize = 300;

    var batch = q.splice(0, batchSize);
    global.set('edge_pg_queue', q);

    node.status({ fill: 'yellow', shape: 'dot', text: 'writing ' + batch.length + '/' + q.length });

    // Check if pg module is available
    if (!pg) {
        // No PG driver — just count and clear (development mode)
        if (DEBUG) node.warn('[PG-Writer] pg not available, discarding ' + batch.length + ' records (dev mode)');
        var total = global.get('edge_pg_success_count') || 0;
        global.set('edge_pg_success_count', total + batch.length);
        // 🔍 输出pg模块不可用
        node.send({ payload: { event: 'no_pg_module', discarded: batch.length, queueSize: q.length } });
        finishWrite(true);
        return;
    }

    // Build parameterized INSERT
    var valStrs = [];
    var params = [];
    var idx = 0;
    batch.forEach(function (r) {
        var vals = [
            r.ts || new Date().toISOString(), r.node_id, r.device_id, r.device_name,
            r.tag_id, r.tag_address, r.tag_name,
            r.raw_value, r.eng_value, r.unit, r.quality, r.host_pc_ip
        ];
        var placeholders = vals.map(function () { idx++; return '$' + idx; });
        valStrs.push('(' + placeholders.join(',') + ')');
        params = params.concat(vals.map(function (v) { return v === undefined ? null : v; }));
    });

    var sql = 'INSERT INTO edgelink.plc_data '
        + '(insert_time,node_id,device_id,device_name,tag_id,tag_address,tag_name,'
        + 'raw_value,eng_value,unit,quality,host_pc_ip) VALUES ' + valStrs.join(',')
        + ' ON CONFLICT (insert_time, tag_id) DO NOTHING';

    // Acquire/reuse pg pool
    var pool = getPool();
    if (!pool) {
        // 🔧 P0#3: 无连接池时 batch 塞回队头，不丢数据
        global.set('edge_pg_writing', false);
        var qRestore = global.get('edge_pg_queue') || [];
        global.set('edge_pg_queue', batch.concat(qRestore));
        var totalQ = batch.length + qRestore.length;
        node.status({ fill: 'red', shape: 'ring', text: 'no pool (' + totalQ + ' queued)' });
        // 🔍 输出无连接池
        node.send({ payload: { event: 'error', reason: 'no_pool', queueSize: totalQ } });
        return;
    }

    var writeStart = Date.now();
    pool.query({ text: sql, values: params }, function (err, result) {
        var elapsed = Date.now() - writeStart;
        if (err) {
            node.warn('[PG-Writer] Write failed (' + elapsed + 'ms): ' + err.message);
            node.status({ fill: 'red', shape: 'ring', text: 'FAIL ' + err.message.substring(0, 20) });
            // 🔧 Track failures
            var fc = global.get('edge_pg_fail_count') || 0;
            global.set('edge_pg_fail_count', fc + batch.length);
            global.set('edge_pg_last_error', err.message);
            // 🔍 输出写入失败
            node.send({ payload: { event: 'error', reason: 'write_failed', elapsed: elapsed, error: err.message, queueSize: (global.get('edge_pg_queue') || []).length } });
            finishWrite(false, batch);
            return;
        } else {
            var count = result.rowCount || batch.length;
            var total = global.get('edge_pg_success_count') || 0;
            global.set('edge_pg_success_count', total + count);
            global.set('edge_pg_last_latency_ms', elapsed);
            global.set('edge_pg_last_error', null);
            // 🔍 输出写入成功（DEBUG模式）
            if (DEBUG) {
                node.send({ payload: { event: 'written', count: count, elapsed: elapsed, queueSize: (global.get('edge_pg_queue') || []).length } });
            }
            if (DEBUG) node.status({ fill: 'green', shape: 'dot', text: count + ' OK ' + elapsed + 'ms' });
        }

        // Adaptive: if write latency > 200ms, reduce batch size for next round
        if (elapsed > 200 && BATCH_SIZE > 50) {
            BATCH_SIZE = Math.max(50, BATCH_SIZE - 25);
        } else if (elapsed < 50 && BATCH_SIZE < 500) {
            BATCH_SIZE = Math.min(500, BATCH_SIZE + 25);
        }
        // 🔧 P1#2: 持久化调整后的 BATCH_SIZE
        global.set('edge_pg_batch_size', BATCH_SIZE);

        // Event-driven: continue if queue has more data
        finishWrite(!err);
    });
}

function getPool() {
    var pool = global.get('edge_pgPool');
    var wanted = {
        host: global.get('edge_pgHost') || '127.0.0.1',
        port: global.get('edge_pgPort') || 5432,
        database: global.get('edge_pgDatabase') || 'postgres',
        user: global.get('edge_pgUser') || 'postgres',
        password: global.get('edge_pgPassword') || '',
        max: 5
    };

    if (pool) {
        var current = pool.options;
        if (current.host === wanted.host && current.port === wanted.port &&
            current.database === wanted.database && current.user === wanted.user &&
            current.password === wanted.password) {
            return pool;
        }
        try { pool.end(); } catch (e) {}
        pool = null;
    }

    if (!pg) return null;
    if (!wanted.password) {
        node.error('[PG-Writer] PG password not configured in settings.js (edge_pgPassword)');
        return null;
    }
    try {
        pool = new pg.Pool(wanted);
        pool.on('error', function (e) {
            node.warn('[PG-Writer] Pool error: ' + e.message);
            global.set('edge_pgPool', null);
        });
        global.set('edge_pgPool', pool);
        // 🔍 输出连接池创建成功
        node.send({ payload: { event: 'pool_created', host: wanted.host, port: wanted.port, database: wanted.database } });
        return pool;
    } catch (e) {
        node.warn('[PG-Writer] Cannot create pool: ' + e.message);
        global.set('edge_pgPool', null);
        // 🔍 输出连接池创建失败
        node.send({ payload: { event: 'error', reason: 'pool_create_failed', error: e.message } });
        return null;
    }
}

function finishWrite(ok, failedBatch) {
    if (!ok) {
        // Requeue failed batch at head, retry after backoff (5s)
        global.set('edge_pg_writing', false);
        var q = global.get('edge_pg_queue') || [];
        global.set('edge_pg_queue', (failedBatch || []).concat(q));
        node.status({ fill: 'red', shape: 'ring', text: 'retry in 5s' });
        setTimeout(function () {
            if (!global.get('edge_pg_writing')) startWrite();
        }, 5000);
        return;
    }
    var q = global.get('edge_pg_queue') || [];
    if (q.length > 0) {
        // More data waiting — continue asynchronously to avoid stack overflow
        setImmediate(doWrite);
    } else {
        // Queue empty — go idle, wait for next input
        global.set('edge_pg_writing', false);
        node.status({ fill: 'green', shape: 'dot', text: 'idle' });
    }
}
